import{_ as a,o as e,c as n,aj as i}from"./chunks/framework.BdtAaXf2.js";const t="/assets/image-20241211180435243.DiLpdMcw.png",p="/assets/image-20241211180518909.o0xMuVIN.png",o="/assets/image-20241211231632255.tYjSNlKH.png",l="/assets/image-20241211232846027.BnVM4gr8.png",E="/assets/image-20241211233119666.DR_uCrL5.png",r="/assets/image-20241211233139036.DhLJkrxx.png",c="/assets/image-20241211233546478.d-o5DoCa.png",g="/assets/image-20241211233632785.D51QB-SU.png",d="/assets/image-20241211233750170.DS7e3gb-.png",m="/assets/image-20241211234341812.CyEYxz7K.png",h="/assets/image-20241211234620705.01SrBAcU.png",B="/assets/image-20241211234427504.DxYBj_zz.png",A="/assets/image-20241211234916982.BmOn4AGo.png",u="/assets/image-20241212000638058.CXGI5uMD.png",_="/assets/image-20241212000808737.HY0Big8r.png",v="/assets/image-20241212000332204.BXIEL2VU.png",k="/assets/image-20241212000847946.7wdldtxY.png",b="/assets/image-20241212001524176.C2xAIkLp.png",D="/assets/image-20241212001606695.DHf1afWb.png",F="/assets/image-20241212001830626.CR9-7njy.png",C="/assets/image-20241212002037085.kyzUacxE.png",S="/assets/image-20241212002125620.mszy3oaI.png",V=JSON.parse('{"title":"02-仓颉开发环境搭建","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/02-仓颉开发环境搭建/02-仓颉开发环境搭建.md","filePath":"仓颉入门到实战/02-仓颉开发环境搭建/02-仓颉开发环境搭建.md","lastUpdated":1733937807000,"__rawMarkdown":"# 02-仓颉开发环境搭建\\n\\n本章节主要介绍如何搭建运行仓颉的开发环境。\\n\\n我们可以将运行仓颉语言的开发环境分成 3 个：\\n\\n1. 仓颉官网提供的在线运行，最低代价的方式来体验和运行仓颉程序。\\n2. 下载安装仓颉 SDK，利用 vscode 安装仓颉语法提示插件，开发仓颉程序\\n3. 在**DevEco Studio** 中安装仓颉插件，开发仓颉程序\\n\\n## 仓颉语言 在线体验\\n\\n打开[https://cangjie-lang.cn/](https://cangjie-lang.cn/)，点击**在线体验**即可\\n\\n![image-20241211180435243](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211180435243.png)\\n\\n---\\n\\n---\\n\\n![image-20241211180518909](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211180518909.png)\\n\\n## vscode 安装仓颉插件\\n\\n### 下载安装 vscode\\n\\n首先我们要下载 vscode 编辑工具，Visual Studio Code（简称“VS Code” [1]）是 Microsoft 在 2015 年 4 月 30 日 Build 开发者大会上正式宣布一个运行于 Mac OS X、Windows 和 Linux 之上的，针对于编写现代 Web 和云应用的跨平台源代码编辑器。\\n\\n[下载地址](https://code.visualstudio.com/)\\n\\n![image-20241211231632255](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211231632255.png)\\n\\n安装成功后，打开是这个样子的。\\n\\n![image-20241211232846027](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211232846027.png)\\n\\n### 下载安装仓颉插件\\n\\n[下载地址](https://cangjie-lang.cn/download)\\n\\n![image-20241211233119666](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233119666.png)\\n\\n建议下载稳定版本，这样少踩一些坑。\\n\\n![image-20241211233139036](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233139036.png)\\n\\n要下载的东西一共两个\\n\\n1. SDK\\n2. vscode 插件\\n\\n![image-20241211233546478](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233546478.png)\\n\\n### 安装仓颉 SDK\\n\\n下载完仓颉 SDK 后，直接双击安装即可\\n\\n![image-20241211233632785](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233632785.png)\\n\\n打开你的终端，输入 命令查看仓颉 SDK 是否安装成功\\n\\n```\\ncjc -v\\n```\\n\\n![image-20241211233750170](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233750170.png)\\n\\n### 安装 vscode 仓颉插件\\n\\n该插件的功能用于让 vscode 识别仓颉语法，和运行仓颉程序。\\n\\n![image-20241211234341812](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211234341812.png)\\n\\n解压它，得到以下程序。\\n\\n![image-20241211234620705](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211234620705.png)\\n\\n---\\n\\nvscode 安装离线插件\\n\\n![image-20241211234427504](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211234427504.png)\\n\\n安装成功\\n\\n![image-20241211234916982](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211234916982.png)\\n\\n此时，需要在 vscode 配置仓颉的 SDK，否则后续无法直接运行仓颉程序。\\n\\n![image-20241212000638058](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212000638058.png)\\n\\n---\\n\\n![image-20241212000808737](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212000808737.png)\\n\\n至此，我们的 vscode 的开发环境都搭好了。\\n\\n## 在**DevEco Studio** 中安装仓颉插件，开发仓颉程序\\n\\n如果想要在在**DevEco Studio** 中安装仓颉插件，开发仓颉程序，那么需要先申请报名。[申请链接](https://developer.huawei.com/consumer/cn/activityDetail/cangjie-beta/)\\n\\n申请通过后，会给你邮箱发送邮件，此时，你根据邮件指引即可。因为此过程在保密范围内，所以就不演示具体的步骤了。\\n\\n安装成功后，会在**DevEco Studio** 中显示仓颉插件选项\\n\\n![image-20241212000332204](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212000332204.png)\\n\\n## 我们第一个仓颉程序\\n\\n接下来，我们就使用 vscode 开发第一个仓颉程序吧！\\n\\n1. 新建一个仓颉文件，后缀名是 **cj**\\n\\n   ![image-20241212000847946](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212000847946.png)\\n\\n2. 输入基本代码\\n\\n   ```c\\n   main() {\\n       println(\\"Hello World\\")\\n   }\\n   ```\\n\\n3. 编译仓颉程序\\n\\n   打开终端，输入以下命令\\n\\n   > cjc 表示使用安装好的 sdk 的内置命令 用来编译仓颉程序\\n   >\\n   > .\\\\01-hello.cj 是要编译的文件\\n   >\\n   > -o hello.exe 表示编译后的内容，生成到 hello.exe\\n\\n   ```js\\n    cjc .\\\\01-hello.cj  -o hello.exe\\n   ```\\n\\n   ![image-20241212001524176](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212001524176.png)\\n\\n4. 运行仓颉程序，此时在终端中输入命令，即可运行我们的仓颉程序\\n\\n   ```\\n    .\\\\hello.exe\\n   ```\\n\\n   ![image-20241212001606695](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212001606695.png)\\n\\n5. 你也可以直接利用 vscode 内置的运行功能，一键编译和运行\\n\\n   ![image-20241212001830626](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212001830626.png)\\n\\n---\\n\\n​ 构建和调试单文件\\n\\n​ ![image-20241212002037085](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212002037085.png)\\n\\n---\\n\\n运行成功\\n\\n![image-20241212002125620](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212002125620.png)\\n\\n## 总结\\n\\n以上就是我们搭建仓颉开发环境的 3 种方式。 下一章节开始介绍基本语法，敬请期待。\\n"}'),x={name:"仓颉入门到实战/02-仓颉开发环境搭建/02-仓颉开发环境搭建.md"};function f(j,s,y,q,K,w){return e(),n("div",null,[...s[0]||(s[0]=[i("",62)])])}const M=a(x,[["render",f]]);export{V as __pageData,M as default};
